/* MyPortfolio R1.6 — Pinball Ratchet V3 integration.
 * Clicks are generated by actual carousel position crossing detents.
 * No looping sound and no synthetic 90ms click trains on selection changes.
 * Space Cadet is a PRIVATE local-import option: never bundled/published.
 */
(()=>{'use strict';
 const $=id=>document.getElementById(id);
 const panel=$('dev-carousel-sound');
 if(!panel || !window.AudioContext && !window.webkitAudioContext) {
   if(panel && $('carousel-audio-status')) $('carousel-audio-status').textContent='Web Audio is unavailable in this browser.';
   return;
 }
 const defaults=Object.freeze({enabled:false,volume:46,motion:55,clicks:2,style:'spin09',settle:true,
   ratchetHaptic:false,selectionHaptic:false,surpriseHaptic:false,hapticPulse:10,clickGap:64});
 const key='portfolio-carousel-sound-r16';
 const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
 const kinds=['spin09','cadet','mechanical','soft','digital','custom'];
 const sanitize=(raw)=>{
   const next={...defaults};
   if(!raw||typeof raw!=='object')return next;
   for(const k of ['enabled','settle','ratchetHaptic','selectionHaptic','surpriseHaptic'])
     if(typeof raw[k]==='boolean')next[k]=raw[k];
   for(const [k,a,b] of [['volume',0,100],['motion',0,100],['clicks',1,3],['hapticPulse',4,35],['clickGap',50,160]])
     if(Number.isFinite(Number(raw[k])) && raw[k]!=null)next[k]=clamp(Math.round(Number(raw[k])),a,b);
   if(kinds.includes(raw.style))next.style=raw.style;
   return next;
 };
 let cfg=sanitize(window.PORTFOLIO_PUBLISHED_CONFIG?.audio?.carousel);
 try{const previous=JSON.parse(localStorage.getItem(key)||'null');if(previous)cfg=sanitize({...cfg,...previous});}catch{}
 const save=()=>{try{localStorage.setItem(key,JSON.stringify(cfg));}catch{}};
 const status=message=>{const el=$('carousel-audio-status');if(el)el.textContent=message;};
 const audioSource=$('carousel-audio-style');
 if(audioSource && !audioSource.querySelector('option[value="cadet"]')){
   const option=document.createElement('option');
   option.value='cadet';option.textContent='Space Cadet · private (load local clip)';
   audioSource.insertBefore(option,audioSource.querySelector('option[value="mechanical"]'));
 }
 // Add controls inside the ORIGINAL Developer Settings group, not a disconnected demo.
 const advanced=document.createElement('div');
 advanced.className='ratchet-v3-extra';
 advanced.innerHTML=
  '<p class="setting-helper"><strong>Pinball Ratchet V3:</strong> real cover movement crosses 1–3 detents per card. Slowing naturally spreads the clicks apart. No sound loops.</p>'+
  '<label class="check-label"><input type="checkbox" id="ratchet-settle"> Soft settle click after motion stops</label>'+
  '<label>Minimum click spacing <output id="ratchet-gap-out">64 ms</output><input type="range" id="ratchet-gap" min="50" max="160" step="2" value="64"></label>'+
  '<div class="ratchet-v3-subtitle">Carousel haptics (Android browsers with vibration support)</div>'+
  '<label class="check-label"><input type="checkbox" id="ratchet-haptic-detent"> Haptic on ratchet crossing</label>'+
  '<label class="check-label"><input type="checkbox" id="ratchet-haptic-select"> Haptic on card selection</label>'+
  '<label class="check-label"><input type="checkbox" id="ratchet-haptic-surprise"> Haptic on Surprise Me</label>'+
  '<label>Haptic pulse duration <output id="ratchet-pulse-out">10 ms</output><input type="range" id="ratchet-pulse" min="4" max="35" value="10"></label>'+
  '<div class="settings-actions"><button id="ratchet-test-haptic" type="button">Test haptic</button></div>'+
  '<small>Vibration amplitude cannot be set by the Web Vibration API. Pulse duration changes perceived feedback, not motor strength. Private uploaded clips stay on this device for this session only.</small>'+
  '<p class="ratchet-v3-readout" id="ratchet-readout" role="status">Waiting for carousel movement.</p>';
 const statusNode=$('carousel-audio-status');
 if(statusNode)statusNode.before(advanced);else panel.appendChild(advanced);
 const css=document.createElement('style');
 css.textContent='.ratchet-v3-extra{border-top:1px solid #b7a4ea55;margin-top:14px;padding-top:10px}.ratchet-v3-extra label{display:block;margin:9px 0}.ratchet-v3-extra label.check-label{display:flex;align-items:center;gap:8px}.ratchet-v3-extra input[type=range]{width:100%;display:block;margin-top:5px}.ratchet-v3-subtitle{font-weight:700;color:#dfc3ff;margin:15px 0 4px}.ratchet-v3-readout{border:1px solid #a2cfc455;background:#061d27;padding:9px 12px;border-radius:9px;font:12px/1.5 ui-monospace,monospace;overflow-wrap:anywhere}.ratchet-v3-extra small{display:block;color:#b7c7d5}';
 document.head.appendChild(css);
 let context=null,master=null,filter=null,bundled=null,bundlePromise=null,custom=null,cadet=null;
 let previousPosition=null,previousDetent=null,previousTime=0,nextAllowed=0,clicked=0,settleTimer=0;
 let lastHaptic=0,dragWasMoving=false,lastReadout=0;
 const isCalm=()=>!!$('motion-toggle')?.checked || !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 function resetPosition(position){
   if(!Number.isFinite(position))return;
   previousPosition=position;previousDetent=Math.round(position*cfg.clicks);
   previousTime=performance.now();dragWasMoving=false;
   clearTimeout(settleTimer);settleTimer=0;
 }
 function unlock(){
   const AC=window.AudioContext||window.webkitAudioContext;
   try{
     if(!context){
       context=new AC();
       master=context.createGain();filter=context.createBiquadFilter();
       filter.type='lowpass';filter.frequency.value=6500;
       master.gain.value=cfg.volume/100*.38;
       master.connect(filter).connect(context.destination);
     }
     if(context.state==='suspended')void context.resume().catch(()=>{});
     return context;
   }catch(err){status('Browser audio could not start: '+(err.message||err));return null;}
 }
 async function loadBundled(){
   if(bundled)return bundled;
   const ac=unlock();if(!ac)return null;
   if(!bundlePromise){
     bundlePromise=fetch('audio/spin-09-click.mp3',{cache:'force-cache'})
       .then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.arrayBuffer();})
       .then(bytes=>ac.decodeAudioData(bytes))
       .then(buffer=>{bundled=buffer;return buffer;})
       .catch(err=>{bundlePromise=null;status('Spin-09 could not load: '+err.message);return null;});
   }
   return bundlePromise;
 }
 function chosenBuffer(){
   if(cfg.style==='spin09')return bundled;
   if(cfg.style==='cadet')return cadet;
   if(cfg.style==='custom')return custom;
   return null;
 }
 function playClick(speed=0,preview=false){
   if(!cfg.enabled || document.hidden || cfg.volume<=0)return;
   const ac=unlock();if(!ac||ac.state!=='running')return;
   const response=cfg.motion/100;
   const velocity=clamp(Math.abs(speed),0,20);
   const rate=clamp((.96+velocity*.011*response)*(1+[0,.018,-.012,.008][clicked%4]),.88,1.22);
   const strength=clamp((.43+velocity*.008*response)*(clicked%3===0?.88:1),.35,.65);
   const buffer=chosenBuffer();
   const t=ac.currentTime;
   const env=ac.createGain();
   const level=clamp(strength,0,.8);
   env.gain.setValueAtTime(Math.max(.0001,level),t);
   env.gain.exponentialRampToValueAtTime(.0001,t+.092);
   env.connect(master);
   if(buffer){
     const voice=ac.createBufferSource();voice.buffer=buffer;voice.playbackRate.value=rate;
     voice.connect(env);voice.start(t,0,Math.min(.09,buffer.duration));
     voice.onended=()=>{voice.disconnect();env.disconnect();};
   }else if(cfg.style==='mechanical'||cfg.style==='soft'||cfg.style==='digital'){
     const voice=ac.createOscillator();
     voice.type=cfg.style==='soft'?'sine':cfg.style==='digital'?'square':'triangle';
     const base=cfg.style==='soft'?270:cfg.style==='digital'?580:390;
     voice.frequency.setValueAtTime(base+velocity*14*response,t);
     voice.frequency.exponentialRampToValueAtTime(base*.65,t+.06);
     voice.connect(env);voice.start(t);voice.stop(t+.08);
     voice.onended=()=>{voice.disconnect();env.disconnect();};
   }else{
     env.disconnect();
     if(preview)status(cfg.style==='cadet'?'Load your private Space Cadet click using the audio picker.':'Choose an audio file to preview.');
   }
 }
 function playSettle(){
   if(!cfg.enabled||!cfg.settle||document.hidden||cfg.volume===0)return;
   const ac=unlock();if(!ac||ac.state!=='running')return;
   const t=ac.currentTime,osc=ac.createOscillator(),env=ac.createGain();
   osc.type='sine';osc.frequency.setValueAtTime(340,t);
   osc.frequency.exponentialRampToValueAtTime(185,t+.035);
   env.gain.setValueAtTime(.1,t);env.gain.exponentialRampToValueAtTime(.0001,t+.048);
   osc.connect(env).connect(master);osc.start(t);osc.stop(t+.052);
   osc.onended=()=>{osc.disconnect();env.disconnect();};
 }
 function haptic(channel){
   if(typeof navigator.vibrate!=='function'||isCalm()||document.hidden)return false;
   const now=performance.now();if(now-lastHaptic<110)return false;
   lastHaptic=now;
   try{
     if(channel==='surprise')return navigator.vibrate([cfg.hapticPulse,80,cfg.hapticPulse,100,cfg.hapticPulse])===true;
     return navigator.vibrate(cfg.hapticPulse)===true;
   }catch{return false;}
 }
 function update({position,velocity=0}={}){
   if(!Number.isFinite(position))return;
   const now=performance.now(),detent=Math.round(position*cfg.clicks);
   if(previousPosition===null){resetPosition(position);return;}
   const delta=position-previousPosition,elapsed=now-previousTime;
   const moved=Math.abs(delta)>.00015;
   // A mode switch, restore, or tab-resume must not simulate many clicks.
   const jumped=elapsed>850||Math.abs(delta)>2.4||elapsed<0;
   const derived=elapsed>1?Math.abs(delta)/(elapsed/1000):0;
   const speed=Number.isFinite(velocity)?Math.max(Math.abs(velocity),derived):derived;
   if(moved){
     clearTimeout(settleTimer);settleTimer=0;
     if(!jumped && detent!==previousDetent && now>=nextAllowed){
       if((cfg.enabled||cfg.ratchetHaptic) && (chosenBuffer() || ['mechanical','soft','digital'].includes(cfg.style))){
         if(cfg.enabled)playClick(speed);
         if(cfg.ratchetHaptic)haptic('detent');
         clicked++;nextAllowed=now+cfg.clickGap;
       }
     }
     if(!jumped&&cfg.settle&&cfg.enabled){
       settleTimer=setTimeout(()=>{settleTimer=0;playSettle();},180);
     }
     dragWasMoving=true;
   }else if(dragWasMoving){dragWasMoving=false;}
   previousPosition=position;previousDetent=detent;previousTime=now;
   if(now-lastReadout>140){
     lastReadout=now;
     const readout=$('ratchet-readout');
     if(readout)readout.textContent=clicked+' clicks · '+speed.toFixed(1)+' covers/s · '+cfg.clicks+' detents/cover';
   }
 }
 function sync(){
   $('carousel-audio-enable').checked=cfg.enabled;
   $('carousel-audio-volume').value=cfg.volume;
   $('carousel-audio-motion').value=cfg.motion;
   $('carousel-audio-clicks').value=cfg.clicks;
   if(audioSource)audioSource.value=cfg.style;
   $('carousel-audio-volume-out').textContent=cfg.volume+'%';
   $('carousel-audio-motion-out').textContent=cfg.motion+'%';
   $('carousel-audio-clicks-out').textContent=String(cfg.clicks);
   $('ratchet-settle').checked=cfg.settle;
   $('ratchet-gap').value=cfg.clickGap;$('ratchet-gap-out').textContent=cfg.clickGap+' ms';
   $('ratchet-haptic-detent').checked=cfg.ratchetHaptic;
   $('ratchet-haptic-select').checked=cfg.selectionHaptic;
   $('ratchet-haptic-surprise').checked=cfg.surpriseHaptic;
   $('ratchet-pulse').value=cfg.hapticPulse;$('ratchet-pulse-out').textContent=cfg.hapticPulse+' ms';
   if(master&&context)master.gain.setTargetAtTime(cfg.volume/100*.38,context.currentTime,.025);
 }
 function change(field,value){
   cfg[field]=value;
   if(field==='clicks'){previousDetent=previousPosition==null?null:Math.round(previousPosition*cfg.clicks);}
   sync();save();
 }
 $('carousel-audio-enable').addEventListener('change',e=>{
   change('enabled',e.target.checked);
   if(cfg.enabled){unlock();if(cfg.style==='spin09')void loadBundled();status('Enabled · position-based ratchet. Swipe, scroll, or press Surprise Me.');}
   else status('Carousel clicks muted. Haptic preferences remain independent.');
 });
 for(const [id,field] of [['carousel-audio-volume','volume'],['carousel-audio-motion','motion'],
  ['carousel-audio-clicks','clicks'],['ratchet-gap','clickGap'],['ratchet-pulse','hapticPulse']]){
   $(id).addEventListener('input',e=>change(field,Number(e.target.value)));
 }
 for(const [id,field] of [['ratchet-settle','settle'],['ratchet-haptic-detent','ratchetHaptic'],
  ['ratchet-haptic-select','selectionHaptic'],['ratchet-haptic-surprise','surpriseHaptic']]){
   $(id).addEventListener('change',e=>change(field,e.target.checked));
 }
 audioSource?.addEventListener('change',e=>{
   change('style',e.target.value);
   if(cfg.style==='spin09')void loadBundled();
   if(cfg.style==='cadet'&&!cadet)status('Private Space Cadet: load your audio clip locally. It will not be published.');
   else if(cfg.style==='custom'&&!custom)status('Choose a local audio clip below.');
   else status('Sound source: '+audioSource.selectedOptions[0].textContent+'.');
 });
 $('carousel-audio-file')?.addEventListener('change',async e=>{
   const file=e.target.files?.[0];if(!file)return;
   if(file.size>2*1024*1024||!/^(audio\/(mpeg|mp3|ogg|wav|x-wav)|application\/ogg)$/.test(file.type)){
     status('Choose an MP3, WAV, or OGG file up to 2 MB.');e.target.value='';return;
   }
   const ac=unlock();if(!ac)return;
   try{
     const decoded=await ac.decodeAudioData(await file.arrayBuffer());
     if(cfg.style==='cadet')cadet=decoded;
     else {custom=decoded;cfg.style='custom';}
     sync();save();status('Loaded '+file.name+' locally. This session only; no private audio is uploaded.');
   }catch(err){status('Cannot decode audio: '+(err.message||err));}
 });
 $('carousel-audio-preview')?.addEventListener('click',async()=>{
   if(!cfg.enabled)change('enabled',true);
   const ac=unlock();if(!ac)return;
   if(cfg.style==='spin09')await loadBundled();
   if(ac.state==='suspended')await ac.resume().catch(()=>{});
   playClick(5,true);
 });
 $('carousel-audio-reset')?.addEventListener('click',()=>{
   cfg={...defaults};cadet=null;custom=null;clicked=0;nextAllowed=0;
   const file=$('carousel-audio-file');if(file)file.value='';
   clearTimeout(settleTimer);settleTimer=0;
   sync();save();status('Ratchet reset. Sound and haptics disabled by default.');
 });
 $('ratchet-test-haptic').addEventListener('click',()=>{
   status(haptic('test')?'Requested '+cfg.hapticPulse+' ms pulse.':'Vibration unavailable or suppressed by reduced-motion/device settings.');
 });
 $('surpriseTrigger')?.addEventListener('click',()=>{
   if(cfg.surpriseHaptic)haptic('surprise');
   if(cfg.enabled){unlock();if(cfg.style==='spin09')void loadBundled();}
 });
 sync();
 status(cfg.style==='cadet'?'Space Cadet is private: load its click locally.':
   'Pinball Ratchet V3 ready · actual detent crossings, no loops. Enable sound to test.');
 // updateInfo() calls this only when selected card changes. Haptics are
 // selection-based; sound is handled solely by update(position).
 window.PortfolioCarouselAudio={
   update,resetPosition,
   tick(_velocity,_project){if(cfg.selectionHaptic)haptic('selection');},
   get:()=>({...cfg}),
   getStats:()=>({clicks:clicked,ready:!!chosenBuffer()||['mechanical','soft','digital'].includes(cfg.style)})
 };
 // Preserve the existing safe, explicit GitHub Mobile publish handoff.
 $('copy-mobile-config')?.addEventListener('click',async()=>{
   const state={version:1,settings:window.PortfolioSettingsController?.get()||{},
     media:window.PortfolioMediaManager?.export?.()||{},
     audio:{carousel:window.PortfolioCarouselAudio?.get()||{}},
     fx:{wp3:window.PortfolioWP3?.get()||{}}};
   const code='/* Published website settings; no secrets. */\nwindow.PORTFOLIO_PUBLISHED_CONFIG='+JSON.stringify(state,null,2)+';\n';
   const msg=$('mobile-publish-status');
   if(code.length>90000){if(msg)msg.textContent='Draft too large. Publish media separately.';return;}
   try{await navigator.clipboard.writeText(code);if(msg)msg.textContent='Copied. Commit on GitHub to develop.';}
   catch{if(msg)msg.textContent='Clipboard blocked. Export draft JSON or use GitHub editor.';}
 });
})();
